import{_ as a,o as t,c as o,a3 as r}from"./chunks/framework.BM_-pWjS.js";const d="/bridge-lite/manual/assets/scan-cancel.BfmY3VLn.png",f=JSON.parse('{"title":"フォルダを開く","description":"","frontmatter":{},"headers":[],"relativePath":"ja/open-folder.md","filePath":"ja/open-folder.md"}'),l={name:"ja/open-folder.md"};function i(n,e,c,s,h,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="フォルダを開く" tabindex="-1">フォルダを開く <a class="header-anchor" href="#フォルダを開く" aria-label="Permalink to &quot;フォルダを開く&quot;">​</a></h1><h2 id="基本的な開き方" tabindex="-1">基本的な開き方 <a class="header-anchor" href="#基本的な開き方" aria-label="Permalink to &quot;基本的な開き方&quot;">​</a></h2><p>起動後、以下のいずれかの方法でフォルダを開きます。</p><ul><li>メニューバー → <strong>「フォルダを開く…」</strong></li><li>フォルダを bridge-lite のウィンドウに<strong>ドラッグ＆ドロップ</strong></li></ul><h2 id="スキャンの仕組み" tabindex="-1">スキャンの仕組み <a class="header-anchor" href="#スキャンの仕組み" aria-label="Permalink to &quot;スキャンの仕組み&quot;">​</a></h2><p>フォルダを開くと、bridge-lite は以下を自動で行います。</p><ol><li>フォルダ内の画像ファイルを再帰的にスキャン</li><li>RAW と JPG を自動ペアリング（ステム名 → EXIF タイムスタンプ → pHash の順）</li><li>サムネイルを生成してキャッシュに保存</li></ol><p>2 回目以降の開き直しはキャッシュを利用するため、大幅に高速化されます。</p><h2 id="対応フォーマット" tabindex="-1">対応フォーマット <a class="header-anchor" href="#対応フォーマット" aria-label="Permalink to &quot;対応フォーマット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>カテゴリ</th><th>フォーマット</th></tr></thead><tbody><tr><td>JPEG</td><td><code>.jpg</code> / <code>.jpeg</code></td></tr><tr><td>RAW</td><td><code>.arw</code>（Sony）/ <code>.cr2</code> / <code>.cr3</code>（Canon）/ <code>.nef</code>（Nikon）/ <code>.raf</code>（Fujifilm）/ <code>.orf</code>（Olympus）/ <code>.pef</code>（Pentax）/ <code>.dng</code></td></tr><tr><td>現像済み</td><td>JPEG・TIFF など、ステム名で RAW と紐づくファイル</td></tr></tbody></table><h2 id="スキャンのキャンセル" tabindex="-1">スキャンのキャンセル <a class="header-anchor" href="#スキャンのキャンセル" aria-label="Permalink to &quot;スキャンのキャンセル&quot;">​</a></h2><p>500 枚程度のフォルダであればスキャンはすぐに完了しますが、1,000 枚を超えると時間がかかったり、動作が重くなることがあります。</p><p>スキャンをキャンセルするには、ウィンドウ左下のボタンを押してください。</p><p><img src="'+d+'" alt="スキャンキャンセルボタン"></p><p>左下のエリアには以下の情報がシークバーで表示されています。</p><ul><li><strong>スキャンで判明した枚数</strong> — フォルダ内で見つかった写真の総数</li><li><strong>サムネイル読み込み完了枚数</strong> — サムネイルの生成が完了している写真数</li></ul><h2 id="メモリカードから直接開く" tabindex="-1">メモリカードから直接開く <a class="header-anchor" href="#メモリカードから直接開く" aria-label="Permalink to &quot;メモリカードから直接開く&quot;">​</a></h2><p>ファイルは一切変更しないため、メモリカードやネットワークドライブをマウントしたまま直接開いても安全です。</p>',18)])])}const _=a(l,[["render",i]]);export{f as __pageData,_ as default};
